import sys
from collections import deque

def solve():
    t_str = sys.stdin.readline()
    if not t_str:
        return
    t = int(t_str)

    for _ in range(t):
        n_str = sys.stdin.readline()
        if not n_str:
            break
        n = int(n_str)

        adj = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u, v = map(int, sys.stdin.readline().split())
            adj[u].append(v)
            adj[v].append(u)

        def query(nodes):
            print(f"? {len(nodes)}", end="")
            for node in nodes:
                print(f" {node}", end="")
            print()
            sys.stdout.flush()

            response = sys.stdin.readline().split()
            x = int(response[0])
            d = int(response[1])
            if x == -1 or d == -1:
                return None, None
            return x, d

        def bfs(start):
            dist = [-1] * (n + 1)
            dist[start] = 0
            q = deque([start])
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        q.append(v)
            return dist

        def get_farthest(dist):
            max_d = -1
            node = 1
            for i in range(1, n + 1):
                if dist[i] > max_d:
                    max_d = dist[i]
                    node = i
            return node, max_d

        all_nodes = list(range(1, n + 1))
        res_node, res_dist = query(all_nodes)
        if res_node is None:
            return

        dist_from_res = bfs(res_node)
        farthest_node, _ = get_farthest(dist_from_res)

        res2_node, res2_dist = query([farthest_node])
        if res2_node is None:
            return

        dist_from_far = bfs(farthest_node)
        farthest_node2, _ = get_farthest(dist_from_far)

        candidates = []
        for i in range(1, n + 1):
            if dist_from_res[i] + dist_from_far[i] == res2_dist:
                candidates.append(i)

        if len(candidates) == 2:
            cand1, cand2 = candidates
            print(f"! {cand1} {cand2}")
            sys.stdout.flush()
            ans = sys.stdin.readline().strip()
            if ans == "Incorrect":
                return
            continue

        if len(candidates) == 1:
            cand1 = candidates[0]
            dist_cand = bfs(cand1)
            for i in range(1, n + 1):
                 if dist_from_res[i] + dist_cand[i] == res_dist:
                     print(f"! {cand1} {i}")
                     sys.stdout.flush()
                     ans = sys.stdin.readline().strip()
                     if ans == "Incorrect":
                         return
                     break
            continue

        best = None
        best_val = float('inf')
        for c in candidates:
            dist_c = bfs(c)
            val = 0
            for i in range(1, n + 1):
               if dist_from_res[i] + dist_c[i] < res_dist:
                   val += 1
            if val < best_val:
                best_val = val
                best = c

        if best is not None:
            cand1 = best
            dist_cand = bfs(cand1)
            for i range(1, n + 1):
                if dist_from_res[i] + dist_cand[i] == res_dist and i != cand1:
                    print(f"! {cand1} {i}")
                    sys.stdout.flush()
                    ans = sys.stdin.readline().strip()
                    if ans == "Incorrect":
                        return
                    break

solve()
